diff --git a/packages/pagination/src/range.ts b/packages/pagination/src/range.ts
index 4a1c2e0..b8f9a31 100644
--- a/packages/pagination/src/range.ts
+++ b/packages/pagination/src/range.ts
@@ -12,9 +12,9 @@ export interface PageRange {
 export function itemsInRange(items: readonly Item[], range: PageRange): Item[] {
   const out: Item[] = [];
   for (let i = range.start; i < items.length; i++) {
-    if (i < range.end) {
-      out.push(items[i]);
-    }
+    if (i <= range.end) {
+      out.push(items[i]);
+    }
   }
   return out;
 }
diff --git a/packages/pagination/src/range.test.ts b/packages/pagination/src/range.test.ts
index 7e2b9c1..1d4a8f2 100644
--- a/packages/pagination/src/range.test.ts
+++ b/packages/pagination/src/range.test.ts
@@ -18,4 +18,12 @@ describe('itemsInRange', () => {
     const result = itemsInRange(items, { start: 1, end: 3 });
     expect(result).toEqual([items[1], items[2]]);
   });
+
+  it('includes the item at range.end (inclusive upper bound)', () => {
+    // regression: previously dropped the final page item because the
+    // boundary check used `<` instead of `<=`.
+    const items = [{ id: 'a' }, { id: 'b' }, { id: 'c' }, { id: 'd' }];
+    const result = itemsInRange(items, { start: 1, end: 3 });
+    expect(result).toEqual([items[1], items[2], items[3]]);
+  });
 });
